import random
from collections import Counter

def task_func(strings: list) -> dict:
    """
    Count occurrences of the literal substring "pattern" in a list of strings.

    Returns:
        dict: {'pattern': total_count}
    """
    target_pattern = "pattern"
    total_count = 0

    for s in strings:
        if isinstance(s, str):
            total_count += s.count(target_pattern)

    return {"pattern": total_count}
